<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php'; admin_required();
require __DIR__ . '/dashboard_v2.php';
exit;
$connection = db();
$stats = $connection->query("SELECT (SELECT COUNT(*) FROM products WHERE status='active') AS products, (SELECT COUNT(*) FROM orders WHERE status IN ('new','confirmed','processing','ready')) AS open_orders, (SELECT COUNT(*) FROM products WHERE stock_quantity <= 5) AS low_stock, COALESCE((SELECT SUM(total_amount) FROM orders WHERE status='completed'),0) AS revenue")->fetch_assoc();
$orders = $connection->query("SELECT o.*, GROUP_CONCAT(CONCAT(oi.quantity, ' × ', oi.product_name) SEPARATOR ', ') AS items FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.id GROUP BY o.id ORDER BY o.created_at DESC LIMIT 12")->fetch_all(MYSQLI_ASSOC);
$lowStock = $connection->query('SELECT name, stock_quantity FROM products WHERE stock_quantity <= reorder_level ORDER BY stock_quantity, name LIMIT 5')->fetch_all(MYSQLI_ASSOC); $success=flash('success'); $error=flash('error');
?>
